func cfftu(tls *libc.TLS, cfft uintptr) {
	if (*cfft_info)(unsafe.Pointer(cfft)).Fwork != 0 {
		faad_free(tls, (*cfft_info)(unsafe.Pointer(cfft)).Fwork)
	}
	if (*cfft_info)(unsafe.Pointer(cfft)).Ftab != 0 {
		faad_free(tls, (*cfft_info)(unsafe.Pointer(cfft)).Ftab)
	}
	if cfft != 0 {
		faad_free(tls, cfft)
	}
}

