// C documentation
//
//	/* Returns the sample rate index based on the samplerate */
func get_sr_index(tls *libc.TLS, samplerate uint32_t) (r uint8_t) {
	if uint32(92017) <= samplerate {
		return uint8(0)
	}
	if uint32(75132) <= samplerate {
		return uint8(1)
	}
	if uint32(55426) <= samplerate {
		return uint8(2)
	}
	if uint32(46009) <= samplerate {
		return uint8(3)
	}
	if uint32(37566) <= samplerate {
		return uint8(4)
	}
	if uint32(27713) <= samplerate {
		return uint8(5)
	}
	if uint32(23004) <= samplerate {
		return uint8(6)
	}
	if uint32(18783) <= samplerate {
		return uint8(7)
	}
	if uint32(13856) <= samplerate {
		return uint8(8)
	}
	if uint32(11502) <= samplerate {
		return uint8(9)
	}
	if uint32(9391) <= samplerate {
		return uint8(10)
	}
	return uint8(11)
}

// C documentation
//
//	/* Returns the sample rate based on the sample rate index */
func get_sample_rate(tls *libc.TLS, sr_index uint8_t) (r uint32_t) {
	if libc.Int32FromUint8(sr_index) < int32(12) {
		return sample_rates[sr_index]
	}
	return uint32(0)
}

