// C documentation
//
//	/* Returns 0 if an object type is decodable, otherwise returns -1 */
func can_decode_ot(tls *libc.TLS, object_type uint8_t) (r int8_t) {
	switch libc.Int32FromUint8(object_type) {
	case int32(LC):
		return 0
	case int32(MAIN):
		return int8(-int32(1))
	case int32(SSR):
		return int8(-int32(1))
	case int32(LTP):
		return int8(-int32(1))
		/* ER object types */
	}
	return int8(-int32(1))
}

func faad_malloc(tls *libc.TLS, size size_t) (r uintptr) {
	return libc.Xmalloc(tls, size)
}

