func huffman_spectral_data(tls *libc.TLS, cb uint8_t, ld uintptr, sp uintptr) (r uint8_t) {
	var err uint8_t
	_ = err
	switch libc.Int32FromUint8(cb) {
	case int32(1): /* 2-step method for data quadruples */
		fallthrough
	case int32(2):
		return huffman_2step_quad(tls, cb, ld, sp)
	case int32(3): /* binary search for data quadruples */
		return huffman_binary_quad_sign(tls, cb, ld, sp)
	case int32(4): /* 2-step method for data quadruples */
		return huffman_2step_quad_sign(tls, cb, ld, sp)
	case int32(5): /* binary search for data pairs */
		return huffman_binary_pair(tls, cb, ld, sp)
	case int32(6): /* 2-step method for data pairs */
		return huffman_2step_pair(tls, cb, ld, sp)
	case int32(7): /* binary search for data pairs */
		fallthrough
	case int32(9):
		return huffman_binary_pair_sign(tls, cb, ld, sp)
	case int32(8): /* 2-step method for data pairs */
		fallthrough
	case int32(10):
		return huffman_2step_pair_sign(tls, cb, ld, sp)
		/* Codebook 12 is disallowed, see `section_data` */
		fallthrough
	case int32(11):
		err = huffman_2step_pair_sign(tls, uint8(11), ld, sp)
		if !(err != 0) {
			err = huffman_getescape(tls, ld, sp)
		}
		if !(err != 0) {
			err = huffman_getescape(tls, ld, sp+1*2)
		}
		return err
	default:
		/* Non existent codebook number, something went wrong */
		return uint8(11)
	}
	/* return 0; */
	return r
}

