func faad_mdct_end(tls *libc.TLS, mdct uintptr) {
	if mdct != libc.UintptrFromInt32(0) {
		cfftu(tls, (*mdct_info)(unsafe.Pointer(mdct)).Fcfft)
		faad_free(tls, mdct)
	}
}

